17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.Collections;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.Map;
25	import java.util.Objects;
26	import java.util.stream.Collectors;
27	
28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.security.core.Authentication;
49	import org.springframework.security.core.context.SecurityContextHolder;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        HttpHeaders headers = new HttpHeaders();
115	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
116	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
117	        owner.setCity(canonicalCity(owner.getCity()));
118	        if (owner.getRegistrationDate() == null) {
119	            owner.setRegistrationDate(LocalDate.now());
120	        }
121	        if (isDailyRegistrationLimitReached()) {
122	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	        }
124	        if (isCityCapacityReached(owner.getCity())) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
128	            return new ResponseEntity<>(HttpStatus.CONFLICT);
129	        }
130	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
131	        owner.setMembershipNumber(membershipNumber);
132	        owner.setCustomerCode(customerCode(owner));
133	        owner.setMembershipTier(membershipNumber <= 100 ? "FOUNDING" : "STANDARD");
134	        owner.setNamesakeCount(namesakeCount(owner));
135	        owner.setSharesHousehold(sharesHousehold(owner));
136	        owner.setLocality(locality(owner));
137	        long sharedAreaCodeCount = sharedAreaCodeCount(owner);
138	        this.clinicService.saveOwner(owner);
139	        auditLogger.info("Owner created by user={} ownerId={} membershipNumber={}",
140	            currentUsername(), owner.getId(), owner.getMembershipNumber());
141	        if (sharedAreaCodeCount >= 5) {
142	            auditLogger.warn("Possible bulk signup: owner={} telephone area code {} shared with {} existing owners",
143	                owner.getId(), areaCode(owner.getTelephone()), sharedAreaCodeCount);
144	        }
145	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
146	        headers.setLocation(UriComponentsBuilder.newInstance()
147	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
148	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
154	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
155	        if (currentOwner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        currentOwner.setAddress(ownerFieldsDto.getAddress());
159	        currentOwner.setCity(ownerFieldsDto.getCity());
160	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
161	        currentOwner.setLastName(ownerFieldsDto.getLastName());
162	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
163	        this.clinicService.saveOwner(currentOwner);
164	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Transactional
169	    @Override
170	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        this.clinicService.deleteOwner(owner);
176	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        HttpHeaders headers = new HttpHeaders();
187	        Pet pet = petMapper.toPet(petFieldsDto);
188	        owner.setId(ownerId);
189	        pet.setOwner(owner);
190	        pet.getType().setName(null);
191	        this.clinicService.savePet(pet);
192	        PetDto petDto = petMapper.toPetDto(pet);
193	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
194	            .buildAndExpand(pet.getId()).toUri());
195	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
201	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
202	        if (currentOwner != null) {
203	            Pet currentPet = this.clinicService.findPetById(petId);
204	            if (currentPet != null) {
205	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
206	                currentPet.setName(petFieldsDto.getName());
207	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
208	                this.clinicService.savePet(currentPet);
209	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	            }
211	        }
212	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
218	        HttpHeaders headers = new HttpHeaders();
219	        Visit visit = visitMapper.toVisit(visitFieldsDto);
220	        Pet pet = new Pet();
221	        pet.setId(petId);
222	        visit.setPet(pet);
223	        this.clinicService.saveVisit(visit);
224	        VisitDto visitDto = visitMapper.toVisitDto(visit);
225	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
226	            .buildAndExpand(visit.getId()).toUri());
227	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
228	    }
229	
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
234	        Owner owner = this.clinicService.findOwnerById(ownerId);
235	        if (owner != null) {
236	            Pet pet = owner.getPet(petId);
237	            if (pet != null) {
238	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
239	            }
240	        }
241	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	    }
243	
244	    /**
245	     * Determines whether an owner conflicting with the given one already exists, i.e. any existing
246	     * owner using the same telephone number.
247	     *
248	     * @param owner the candidate owner to check
249	     * @return {@code true} if another owner already uses the telephone number, {@code false} otherwise
250	     */
251	    /**
252	     * Builds the customer code assigned to a newly created owner, formatted as
253	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
254	     * already registered in the same city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
255	     *
256	     * @param owner the owner being created
257	     * @return the customer code for the owner
258	     */
259	    /**
260	     * Counts how many other owners already share the given owner's last name at the moment of
261	     * creation. The owner being created is not yet persisted and so is not included in the count.
262	     *
263	     * @param owner the owner being created
264	     * @return the number of existing owners with the same last name
265	     */
266	    /**
267	     * Determines whether the newly created owner shares a household with an existing owner, i.e.
268	     * whether another owner already has the same address and city. Both values are matched
269	     * case- and whitespace-insensitively.
270	     *
271	     * @param owner the owner being created
272	     * @return {@code true} if another owner already has the same address and city, {@code false} otherwise
273	     */
274	    private boolean sharesHousehold(Owner owner) {
275	        String address = normalize(owner.getAddress());
276	        String city = normalize(owner.getCity());
277	        return this.clinicService.findAllOwners().stream()
278	            .anyMatch(existing -> Objects.equals(address, normalize(existing.getAddress()))
279	                && Objects.equals(city, normalize(existing.getCity())));
280	    }
281	
282	    /**
283	     * Determines the locality of a newly created owner. The owner is {@code "local"} if their city
284	     * is the single most common city among the owners that already exist at the moment of creation
285	     * (i.e. strictly more owners live there than in any other city); otherwise the owner is
286	     * {@code "remote"}. When no owners yet exist, or when several cities are tied for most common,
287	     * the owner is {@code "remote"}. Cities are matched case- and whitespace-insensitively.
288	     *
289	     * @param owner the owner being created
290	     * @return {@code "local"} or {@code "remote"}
291	     */
292	    private String locality(Owner owner) {
293	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
294	            .map(existing -> normalize(existing.getCity()))
295	            .filter(Objects::nonNull)
296	            .collect(Collectors.groupingBy(city -> city, Collectors.counting()));
297	        if (countsByCity.isEmpty()) {
298	            return "remote";
299	        }
300	        long max = Collections.max(countsByCity.values());
301	        List<String> mostCommon = countsByCity.entrySet().stream()
302	            .filter(entry -> entry.getValue() == max)
303	            .map(Map.Entry::getKey)
304	            .toList();
305	        if (mostCommon.size() == 1 && mostCommon.get(0).equals(normalize(owner.getCity()))) {
306	            return "local";
307	        }
308	        return "remote";
309	    }
310	
311	    private int namesakeCount(Owner owner) {
312	        String lastName = owner.getLastName();
313	        return (int) this.clinicService.findAllOwners().stream()
314	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
315	            .count();
316	    }
317	
318	    private String customerCode(Owner owner) {
319	        String city = owner.getCity();
320	        long existingInCity = this.clinicService.findAllOwners().stream()
321	            .filter(existing -> Objects.equals(existing.getCity(), city))
322	            .count();
323	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
324	    }
325	
326	    /**
327	     * Determines the canonical spelling of the city for a newly created owner. If another owner
328	     * already lives in the same city (matched case- and whitespace-insensitively), that owner's exact
329	     * spelling of the city name is reused so that all owners in a city share a consistent value.
330	     * Otherwise the supplied city is title-cased (e.g. {@code "new york"} becomes {@code "New York"}).
331	     *
332	     * @param city the raw city as supplied when creating the owner, may be {@code null}
333	     * @return the canonical city spelling, or {@code null} if {@code city} was {@code null}
334	     */
335	    private String canonicalCity(String city) {
336	        if (city == null) {
337	            return null;
338	        }
339	        String normalized = normalize(city);
340	        for (Owner existing : this.clinicService.findAllOwners()) {
341	            if (existing.getCity() != null && normalized.equals(normalize(existing.getCity()))) {
342	                return existing.getCity();
343	            }
344	        }
345	        return titleCase(city);
346	    }
347	
348	    /**
349	     * Title-cases a value by upper-casing the first letter of every whitespace-separated word and
350	     * lower-casing the rest, collapsing any run of internal whitespace to a single space (e.g.
351	     * {@code "new  YORK city"} becomes {@code "New York City"}).
352	     *
353	     * @param value the value to title-case
354	     * @return the title-cased value
355	     */
356	    private static String titleCase(String value) {
357	        StringBuilder result = new StringBuilder();
358	        for (String word : value.strip().split("\\s+")) {
359	            if (word.isEmpty()) {
360	                continue;
361	            }
362	            if (result.length() > 0) {
363	                result.append(' ');
364	            }
365	            result.append(Character.toUpperCase(word.charAt(0)))
366	                .append(word.substring(1).toLowerCase(Locale.ROOT));
367	        }
368	        return result.toString();
369	    }
370	
371	    /**
372	     * Determines whether the maximum number of owners allowed to be registered on a single day has
373	     * already been reached. At most 20 owners may be created with today's registration date; once
374	     * that many exist, further registrations for today are rejected.
375	     *
376	     * @return {@code true} if 20 or more owners already have today's registration date
377	     */
378	    private boolean isDailyRegistrationLimitReached() {
379	        LocalDate today = LocalDate.now();
380	        long registeredToday = this.clinicService.findAllOwners().stream()
381	            .filter(existing -> today.equals(existing.getRegistrationDate()))
382	            .count();
383	        return registeredToday >= 20;
384	    }
385	
386	    /**
387	     * Determines whether the city of a newly created owner has already reached its capacity. At most
388	     * 8 owners may live in a single city; once a city already contains 8 owners, further registrations
389	     * for that city are rejected. Cities are matched case- and whitespace-insensitively so that
390	     * differing spellings of the same city name count towards the same limit.
391	     *
392	     * @param city the canonical city of the owner being created, may be {@code null}
393	     * @return {@code true} if the city already contains 8 or more owners, {@code false} otherwise
394	     */
395	    private boolean isCityCapacityReached(String city) {
396	        String normalized = normalize(city);
397	        long existingInCity = this.clinicService.findAllOwners().stream()
398	            .filter(existing -> Objects.equals(normalized, normalize(existing.getCity())))
399	            .count();
400	        return existingInCity >= 8;
401	    }
402	
403	    /**
404	     * Returns the name of the currently authenticated user, or {@code "anonymous"} when there is no
405	     * authentication in the security context.
406	     *
407	     * @return the authenticated user's name
408	     */
409	    private static String currentUsername() {
410	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
411	        return authentication != null ? authentication.getName() : "anonymous";
412	    }
413	
414	    /**
415	     * Counts how many existing owners share the given owner's telephone area code (the first three
416	     * digits of the normalised, digits-only telephone number). The owner being created is not yet
417	     * persisted and so is not included in the count. Owners whose telephone has fewer than three
418	     * digits (or no area code) never match.
419	     *
420	     * @param owner the owner being created
421	     * @return the number of existing owners sharing the owner's telephone area code
422	     */
423	    private long sharedAreaCodeCount(Owner owner) {
424	        String areaCode = areaCode(owner.getTelephone());
425	        if (areaCode == null) {
426	            return 0;
427	        }
428	        return this.clinicService.findAllOwners().stream()
429	            .filter(existing -> areaCode.equals(areaCode(existing.getTelephone())))
430	            .count();
431	    }
432	
433	    /**
434	     * Extracts the area code (first three digits) of a normalised, digits-only telephone number.
435	     *
436	     * @param telephone the telephone number, may be {@code null}
437	     * @return the first three digits, or {@code null} if the number is {@code null} or has fewer than
438	     *         three digits
439	     */
440	    private static String areaCode(String telephone) {
441	        if (telephone == null || telephone.length() < 3) {
442	            return null;
443	        }
444	        return telephone.substring(0, 3);
445	    }
446	
447	    private boolean isDuplicateOwner(Owner owner) {
448	        return this.clinicService.findAllOwners().stream()
449	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
450	    }
451	
452	    /**
453	     * Normalises a telephone number to digits only by stripping spaces, dashes and parentheses (and
454	     * any other non-digit characters). This is applied before storing the number and before the
455	     * telephone-uniqueness check, so that e.g. {@code "(613) 555-0100"} and {@code "6135550100"} are
456	     * stored identically and treated as the same number.
457	     *
458	     * @param telephone the raw telephone number, may be {@code null}
459	     * @return the digits-only telephone number, or {@code null} if {@code telephone} was {@code null}
460	     */
461	    private static String normalizeTelephone(String telephone) {
462	        if (telephone == null) {
463	            return null;
464	        }
465	        return telephone.replaceAll("[^0-9]", "");
466	    }
467	
468	    /**
469	     * Determines whether the given owner's email address is already used by another owner. An owner
470	     * without an email address never conflicts. The comparison is case-insensitive and ignores
471	     * surrounding or repeated whitespace, so e.g. {@code "  John.Smith@Example.com "} and
472	     * {@code "john.smith@example.com"} are treated as the same address.
473	     *
474	     * @param owner the candidate owner to check
475	     * @return {@code true} if another owner already uses the email address, {@code false} otherwise
476	     */
