package org.springframework.samples.petclinic.rest.controller.v1;

import java.time.LocalDate;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.mapper.PetMapper;
import org.springframework.samples.petclinic.mapper.VisitMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.Pet;
import org.springframework.samples.petclinic.model.Visit;
import org.springframework.samples.petclinic.rest.api.OwnersApi;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.PetDto;
import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
import org.springframework.samples.petclinic.rest.dto.VisitDto;
import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.util.UriComponentsBuilder;

import jakarta.transaction.Transactional;

/**
 * @author Vitaliy Fedoriv
 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
        owner.setCity(canonicalCity(owner.getCity()));
        if (owner.getRegistrationDate() == null) {
            owner.setRegistrationDate(LocalDate.now());
        }
        if (isDailyRegistrationLimitReached()) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        if (isCityCapacityReached(owner.getCity())) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }
        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
        owner.setMembershipNumber(membershipNumber);
        owner.setCustomerCode(customerCode(owner));
        owner.setMembershipTier(membershipNumber <= 100 ? "FOUNDING" : "STANDARD");
        owner.setNamesakeCount(namesakeCount(owner));
        owner.setSharesHousehold(sharesHousehold(owner));
        owner.setLocality(locality(owner));
        long sharedAreaCodeCount = sharedAreaCodeCount(owner);
        this.clinicService.saveOwner(owner);
        auditLogger.info("Owner created by user={} ownerId={} membershipNumber={}",
            currentUsername(), owner.getId(), owner.getMembershipNumber());
        if (sharedAreaCodeCount >= 5) {
            auditLogger.warn("Possible bulk signup: owner={} telephone area code {} shared with {} existing owners",
                owner.getId(), areaCode(owner.getTelephone()), sharedAreaCodeCount);
        }
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        currentOwner.setAddress(ownerFieldsDto.getAddress());
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        this.clinicService.deleteOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    /**
     * Determines whether an owner conflicting with the given one already exists, i.e. any existing
     * owner using the same telephone number.
     *
     * @param owner the candidate owner to check
     * @return {@code true} if another owner already uses the telephone number, {@code false} otherwise
     */
    /**
     * Builds the customer code assigned to a newly created owner, formatted as
     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
     * already registered in the same city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
     *
     * @param owner the owner being created
     * @return the customer code for the owner
     */
    /**
     * Counts how many other owners already share the given owner's last name at the moment of
     * creation. The owner being created is not yet persisted and so is not included in the count.
     *
     * @param owner the owner being created
     * @return the number of existing owners with the same last name
     */
    /**
     * Determines whether the newly created owner shares a household with an existing owner, i.e.
     * whether another owner already has the same address and city. Both values are matched
     * case- and whitespace-insensitively.
     *
     * @param owner the owner being created
     * @return {@code true} if another owner already has the same address and city, {@code false} otherwise
     */
    private boolean sharesHousehold(Owner owner) {
        String address = normalize(owner.getAddress());
        String city = normalize(owner.getCity());
        return this.clinicService.findAllOwners().stream()
            .anyMatch(existing -> Objects.equals(address, normalize(existing.getAddress()))
                && Objects.equals(city, normalize(existing.getCity())));
    }

    /**
     * Determines the locality of a newly created owner. The owner is {@code "local"} if their city
     * is the single most common city among the owners that already exist at the moment of creation
     * (i.e. strictly more owners live there than in any other city); otherwise the owner is
     * {@code "remote"}. When no owners yet exist, or when several cities are tied for most common,
     * the owner is {@code "remote"}. Cities are matched case- and whitespace-insensitively.
     *
     * @param owner the owner being created
     * @return {@code "local"} or {@code "remote"}
     */
    private String locality(Owner owner) {
        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
            .map(existing -> normalize(existing.getCity()))
            .filter(Objects::nonNull)
            .collect(Collectors.groupingBy(city -> city, Collectors.counting()));
        if (countsByCity.isEmpty()) {
            return "remote";
        }
        long max = Collections.max(countsByCity.values());
        List<String> mostCommon = countsByCity.entrySet().stream()
            .filter(entry -> entry.getValue() == max)
            .map(Map.Entry::getKey)
            .toList();
        if (mostCommon.size() == 1 && mostCommon.get(0).equals(normalize(owner.getCity()))) {
            return "local";
        }
        return "remote";
    }

    private int namesakeCount(Owner owner) {
        String lastName = owner.getLastName();
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
            .count();
    }

    private String customerCode(Owner owner) {
        String city = owner.getCity();
        long existingInCity = this.clinicService.findAllOwners().stream()
            .filter(existing -> Objects.equals(existing.getCity(), city))
            .count();
        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
    }

    /**
     * Determines the canonical spelling of the city for a newly created owner. If another owner
     * already lives in the same city (matched case- and whitespace-insensitively), that owner's exact
     * spelling of the city name is reused so that all owners in a city share a consistent value.
     * Otherwise the supplied city is title-cased (e.g. {@code "new york"} becomes {@code "New York"}).
     *
     * @param city the raw city as supplied when creating the owner, may be {@code null}
     * @return the canonical city spelling, or {@code null} if {@code city} was {@code null}
     */
    private String canonicalCity(String city) {
        if (city == null) {
            return null;
        }
        String normalized = normalize(city);
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (existing.getCity() != null && normalized.equals(normalize(existing.getCity()))) {
                return existing.getCity();
            }
        }
        return titleCase(city);
    }

    /**
     * Title-cases a value by upper-casing the first letter of every whitespace-separated word and
     * lower-casing the rest, collapsing any run of internal whitespace to a single space (e.g.
     * {@code "new  YORK city"} becomes {@code "New York City"}).
     *
     * @param value the value to title-case
     * @return the title-cased value
     */
    private static String titleCase(String value) {
        StringBuilder result = new StringBuilder();
        for (String word : value.strip().split("\\s+")) {
            if (word.isEmpty()) {
                continue;
            }
            if (result.length() > 0) {
                result.append(' ');
            }
            result.append(Character.toUpperCase(word.charAt(0)))
                .append(word.substring(1).toLowerCase(Locale.ROOT));
        }
        return result.toString();
    }

    /**
     * Determines whether the maximum number of owners allowed to be registered on a single day has
     * already been reached. At most 20 owners may be created with today's registration date; once
     * that many exist, further registrations for today are rejected.
     *
     * @return {@code true} if 20 or more owners already have today's registration date
     */
    private boolean isDailyRegistrationLimitReached() {
        LocalDate today = LocalDate.now();
        long registeredToday = this.clinicService.findAllOwners().stream()
            .filter(existing -> today.equals(existing.getRegistrationDate()))
            .count();
        return registeredToday >= 20;
    }

    /**
     * Determines whether the city of a newly created owner has already reached its capacity. At most
     * 8 owners may live in a single city; once a city already contains 8 owners, further registrations
     * for that city are rejected. Cities are matched case- and whitespace-insensitively so that
     * differing spellings of the same city name count towards the same limit.
     *
     * @param city the canonical city of the owner being created, may be {@code null}
     * @return {@code true} if the city already contains 8 or more owners, {@code false} otherwise
     */
    private boolean isCityCapacityReached(String city) {
        String normalized = normalize(city);
        long existingInCity = this.clinicService.findAllOwners().stream()
            .filter(existing -> Objects.equals(normalized, normalize(existing.getCity())))
            .count();
        return existingInCity >= 8;
    }

    /**
     * Returns the name of the currently authenticated user, or {@code "anonymous"} when there is no
     * authentication in the security context.
     *
     * @return the authenticated user's name
     */
    private static String currentUsername() {
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        return authentication != null ? authentication.getName() : "anonymous";
    }

    /**
     * Counts how many existing owners share the given owner's telephone area code (the first three
     * digits of the normalised, digits-only telephone number). The owner being created is not yet
     * persisted and so is not included in the count. Owners whose telephone has fewer than three
     * digits (or no area code) never match.
     *
     * @param owner the owner being created
     * @return the number of existing owners sharing the owner's telephone area code
     */
    private long sharedAreaCodeCount(Owner owner) {
        String areaCode = areaCode(owner.getTelephone());
        if (areaCode == null) {
            return 0;
        }
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> areaCode.equals(areaCode(existing.getTelephone())))
            .count();
    }

    /**
     * Extracts the area code (first three digits) of a normalised, digits-only telephone number.
     *
     * @param telephone the telephone number, may be {@code null}
     * @return the first three digits, or {@code null} if the number is {@code null} or has fewer than
     *         three digits
     */
    private static String areaCode(String telephone) {
        if (telephone == null || telephone.length() < 3) {
            return null;
        }
        return telephone.substring(0, 3);
    }

    private boolean isDuplicateOwner(Owner owner) {
        return this.clinicService.findAllOwners().stream()
            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
    }

    /**
     * Normalises a telephone number to digits only by stripping spaces, dashes and parentheses (and
     * any other non-digit characters). This is applied before storing the number and before the
     * telephone-uniqueness check, so that e.g. {@code "(613) 555-0100"} and {@code "6135550100"} are
     * stored identically and treated as the same number.
     *
     * @param telephone the raw telephone number, may be {@code null}
     * @return the digits-only telephone number, or {@code null} if {@code telephone} was {@code null}
     */
    private static String normalizeTelephone(String telephone) {
        if (telephone == null) {
            return null;
        }
        return telephone.replaceAll("[^0-9]", "");
    }

    /**
     * Determines whether the given owner's email address is already used by another owner. An owner
     * without an email address never conflicts. The comparison is case-insensitive and ignores
     * surrounding or repeated whitespace, so e.g. {@code "  John.Smith@Example.com "} and
     * {@code "john.smith@example.com"} are treated as the same address.
     *
     * @param owner the candidate owner to check
     * @return {@code true} if another owner already uses the email address, {@code false} otherwise
     */
    private boolean isDuplicateEmail(Owner owner) {
        String email = normalize(owner.getEmail());
        if (email == null || email.isEmpty()) {
            return false;
        }
        return this.clinicService.findAllOwners().stream()
            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
    }

    /**
     * Normalises a value for case- and whitespace-insensitive duplicate detection: surrounding
     * whitespace is stripped, any run of internal whitespace is collapsed to a single space and all
     * letters are lower-cased. This is what makes {@code "  john   smith "} and {@code "John Smith"}
     * count as the same person (or, for e-mail, the same address) when detecting duplicates.
     *
     * @param value the raw value, may be {@code null}
     * @return the normalised value, or {@code null} if {@code value} was {@code null}
     */
    private static String normalize(String value) {
        if (value == null) {
            return null;
        }
        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

